python3 -c "import zipfile, re;
def read_pptx(path):
    try:
        with zipfile.ZipFile(path) as z:
            slides = [n for n in z.namelist() if n.startswith('ppt/slides/slide')]
            text = ''
            for s in slides:
                text += re.sub('<[^>]+>', '', z.read(s).decode('utf-8')) + ' '
            return text[:500]
    except Exception as e: return str(e)

print('DAMOP:', read_pptx('papers/all/DAMOP.pptx'))
"

